#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Simple Greedy: Find minimum coins to make change
// (Works for standard denominations like 1, 5, 10, 25)
int main() {
    int amount;
    cin >> amount;

    vector<int> coins = {25, 10, 5, 1};
    int totalCoins = 0;

    for (int coin : coins) {
        int count = amount / coin;  // Greedy: use as many large coins as possible
        totalCoins += count;
        amount -= count * coin;
        if (count > 0)
            cout << coin << " cent: " << count << " coins" << endl;
    }

    cout << "Total coins: " << totalCoins << endl;
    return 0;
}

