#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<pair<int,int>> activities(n); // {finish, start}
    for (int i = 0; i < n; i++) {
        int s, f;
        cin >> s >> f;
        activities[i] = {f, s}; // Store finish first for sorting
    }

    // Step 1: Sort by finish time
    sort(activities.begin(), activities.end());

    // Step 2: Select first activity
    int count = 1;
    int lastFinish = activities[0].first;
    cout << "Selected: (" << activities[0].second << "," << activities[0].first << ")";

    // Step 3: Greedily select compatible activities
    for (int i = 1; i < n; i++) {
        if (activities[i].second >= lastFinish) {
            count++;
            lastFinish = activities[i].first;
            cout << " (" << activities[i].second << "," << activities[i].first << ")";
        }
    }

    cout << endl << "Max activities: " << count << endl;
    return 0;
}

