#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char ch;
    int freq;
    struct Node *left, *right;
} Node;

Node* nodes[256];
int heapSize = 0;

void swap(int i, int j) { Node* t = nodes[i]; nodes[i] = nodes[j]; nodes[j] = t; }

void pushHeap(Node* n) {
    nodes[heapSize++] = n;
    int i = heapSize - 1;
    while (i > 0 && nodes[i]->freq < nodes[(i-1)/2]->freq) { swap(i, (i-1)/2); i = (i-1)/2; }
}

Node* popHeap() {
    Node* top = nodes[0];
    nodes[0] = nodes[--heapSize];
    int i = 0;
    while (2*i+1 < heapSize) {
        int s = 2*i+1;
        if (s+1 < heapSize && nodes[s+1]->freq < nodes[s]->freq) s++;
        if (nodes[i]->freq <= nodes[s]->freq) break;
        swap(i, s); i = s;
    }
    return top;
}

void printCodes(Node* root, char* code, int depth) {
    if (!root) return;
    if (!root->left && !root->right) { code[depth] = '\0'; printf("%c: %s\n", root->ch, code); }
    code[depth] = '0'; printCodes(root->left, code, depth + 1);
    code[depth] = '1'; printCodes(root->right, code, depth + 1);
}

int main() {
    char s[1001];
    scanf("%s", s);
    int freq[256] = {0};
    for (int i = 0; s[i]; i++) freq[(int)s[i]]++;
    for (int i = 0; i < 256; i++) {
        if (freq[i]) {
            Node* n = malloc(sizeof(Node));
            n->ch = i; n->freq = freq[i]; n->left = n->right = NULL;
            pushHeap(n);
        }
    }
    while (heapSize > 1) {
        Node *l = popHeap(), *r = popHeap();
        Node* p = malloc(sizeof(Node));
        p->ch = '\0'; p->freq = l->freq + r->freq; p->left = l; p->right = r;
        pushHeap(p);
    }
    char code[256];
    printCodes(nodes[0], code, 0);
    return 0;
}
